import java.util.*;

public class C {

    static long[] ONES = new long[17];
    static {
        fillOnes();
    }
    static void fillOnes() {
        ONES[1] = 1;
        for (int i = 2; i < 17; i++) {
            ONES[i] = 10 * ONES[i - 1] + 1;
        }
    }

    long go(long x, int len) {
        x = Math.abs(x);
        if (x % ONES[len] == 0) {
            return x / ONES[len] * len;
        }
        long low = x / ONES[len];
        long high = low + 1;
        long ret1 = low * len + go(x - low * ONES[len], len - 1);
        long ret2 = high * len + go(high * ONES[len] - x, len - 1);
        return Math.min(ret1, ret2);
    }

    long solve(long x) {
        return go(x, 16);
    }

    C() {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        sc.close();
        System.out.println(solve(x));
    }

    public static void main(String[] args) {
        new C();
    }
}
